var catalogueCache={}, sourceIcon='<svg viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="8" width="38" height="32" rx="7" fill="#42325e" stroke="#bea0ec" stroke-width="3"/><path d="M19 17l13 7-13 7Z" fill="#85e1db"/><path d="M11 14h2m-2 10h2m-2 10h2m22-20h2m-2 10h2m-2 10h2" stroke="#d7c5f7" stroke-width="3" stroke-linecap="round"/></svg>';
var api = window.ISRStudios = {version:'1.1.0', studios:studios};
function open(studio) {
 Lampa.Activity.push({component:'main',source:source,title:studio ? studio.title : 'Студии',isr_studio:studio ? studio.key : '',page:1,url:''});
}
function tile(studio) {
 return {source:'custom',isr_studio_tile:true,title:studio.title,name:studio.title,params:{
  createInstance:function(element){return Lampa.Maker.make('Card',element,function(module){return module.only('Card','Callback');});},
  emit:{onCreate:function(){
   this.html.addClass('isr-studio-tile');
   this.html.find('.card__img').remove();
   var view=this.html.find('.card__view'),wrap=$('<div class="isr-studio-logo"></div>'),img=$('<img>').attr({src:studio.logo,alt:studio.title,decoding:'async'});
   if(studio.monoWhite)img.addClass('isr-studio-logo--white');
   if(studio.lightBackground)view.addClass('isr-studio-tile--light');
   img.on('error',function(){wrap.empty().text(studio.title);});
   wrap.append(img);view.append(wrap);
  },onlyEnter:function(){open(studio);}}
 }};
}
function profiles(studio,counts) {
 var rows=[],today=new Date().toISOString().slice(0,10),year=Number(today.slice(0,4));
 counts=counts||studio.counts||{};
 var small=typeof counts.movie==='number'&&typeof counts.tv==='number'&&counts.movie+counts.tv<20;
 (small?['popular']:['new','popular','rating','audience']).forEach(function(sort){
  ['movie','tv'].forEach(function(type){
   if(counts[type]===0)return;
   var field=type==='tv'?'first_air_date':'primary_release_date';
   var order=sort==='new'?field+'.desc':sort==='popular'?'popularity.desc':sort==='rating'?'vote_average.desc':'vote_count.desc';
   var url='discover/'+type+'?with_companies='+studio.ids.join('|')+'&include_adult=false&'+field+'.lte='+today+'&sort_by='+order;
   if(sort==='new')url+='&'+field+'.gte='+(year-2)+'-01-01';
   if(sort==='rating')url+='&vote_average.gte=7&vote_count.gte='+(studio.group==='Российские и советские'?10:50);
   if(sort==='audience')url+='&vote_average.gte=6&vote_count.gte=50';
   rows.push({type:type,sort:sort,url:url,title:({popular:'Популярные',new:'Новинки',rating:'Высокий рейтинг',audience:'Выбор зрителей'})[sort]+' · '+(type==='movie'?'Фильмы':'Сериалы')});
  });
 });return rows;
}
function list(params,ok,bad){
 var tmdb=Lampa.Api.sources.tmdb,method=String(params.url||''),type=/^discover\/tv/.test(method)?'tv':'movie';
 if(!tmdb||typeof tmdb.get!=='function'){if(bad)bad();return;}
 // A production-company catalogue must not inherit a global minimum vote count.
 // Native TMDB keeps the installation's own TMDB proxy and configured API key.
 var p={page:params.page||1,langs:'ru-RU'};
 tmdb.get(method,p,function(d){
  if(!d||!Array.isArray(d.results)){if(bad)bad();return;}
  d.results=d.results.filter(function(c){return c&&!c.adult&&(!window.ISRContentPolicy||!ISRContentPolicy.blocked(c));});
  d.results.forEach(function(c){c.source='tmdb';c.media_type=type;});
  // Prefer Russian titles without hiding films whose original title is English.
  d.results=d.results.map(function(c,i){return {card:c,index:i,ru:/[А-Яа-яЁё]/.test(c.title||c.name||'')};}).sort(function(a,b){return Number(b.ru)-Number(a.ru)||a.index-b.index;}).map(function(c){return c.card;});
  d.url=method;d.source=source;d.page=Number(d.page)||p.page;ok(d);
 },bad);
}
function loadCatalogue(studio,ok,bad){
 var cached=catalogueCache[studio.key];
 if(cached&&cached.until>Date.now()){ok(cached);return;}
 var counts={},popular={},left=2,failed=0;
 ['movie','tv'].forEach(function(type){
  var profile=profiles(studio,{movie:20,tv:20}).filter(function(p){return p.sort==='popular'&&p.type===type;})[0];
  list({url:profile.url,page:1},function(d){counts[type]=Number(d.total_results)||d.results.length;popular[type]=d;done();},function(){failed++;done();});
 });
 function done(){
  if(--left)return;
  if(failed===2){if(bad)bad();return;}
  var entry={counts:counts,popular:popular,until:Date.now()+1800000};
  // Keep only recently opened studios in memory, independent of personal data.
  var keys=Object.keys(catalogueCache);if(keys.length>=12)delete catalogueCache[keys[0]];
  if(!failed)catalogueCache[studio.key]=entry;ok(entry);
 }
}
function main(params,ok,bad){
 var studio=studios.filter(function(s){return s.key===params.isr_studio;})[0],rows;
 if(params.isr_studio&&!studio){if(bad)bad();return;}
 var loading=false,waiting=[],catalogue;
 if(!studio){
  var groups=[];studios.forEach(function(s){if(groups.indexOf(s.group)<0)groups.push(s.group);});
  rows=groups.map(function(group){return function(cb){cb({title:group,results:studios.filter(function(s){return s.group===group;}).map(tile),nomore:true,params:{nomore:true},more:false,total_pages:1});};});
 }
 function next(a,b){
  if(rows){Lampa.Api.partNext(rows,3,a,b);return;}
  waiting.push([a,b]);if(loading)return;loading=true;
  loadCatalogue(studio,function(data){
   catalogue=data;
   rows=profiles(studio,data.counts).map(function(profile){return function(cb){
    var cached=profile.sort==='popular'&&catalogue.popular[profile.type];
    function finish(d){cb($.extend({},d,{title:profile.title}));}
    if(cached)finish(cached);else list({url:profile.url,page:1},finish,function(){cb({title:profile.title,results:[]});});
   };});
   var queue=waiting;waiting=[];loading=false;queue.forEach(function(pair){next(pair[0],pair[1]);});
  },function(){var queue=waiting;waiting=[];loading=false;queue.forEach(function(pair){if(pair[1])pair[1]();});});
 }
 next(ok,bad);return next;
}

function menu(){
 var list=$('.menu .menu__list').first();if(!list.length)return;
 var button=list.children('[data-action="isr-studios"]');
 if(!button.length){button=$('<li class="menu__item selector" data-action="isr-studios"><div class="menu__ico">'+sourceIcon+'</div><div class="menu__text">Студии</div></li>');button.on('hover:enter',function(){open();});list.append(button);}
 if(window.ISRSections&&typeof ISRSections.colorMenu==='function')ISRSections.colorMenu();
}
