 Lampa.Api.sources[source]={SOURCE_NAME:source,SOURCE_TITLE:'Студии',main:main,category:main,list:list,full:Lampa.Api.sources.tmdb.full,menu:function(p,cb){cb([]);},menuCategory:function(p,cb){cb([]);},clear:function(){}};
